#!/usr/bin/env bash
# Build the signed Android App Bundle (.aab) for Google Play. Like release-ios.sh,
# android/ is generated by `expo prebuild` (gitignored) and regenerated from app.json
# before every build. Version and version code live in app.json (expo.version,
# expo.android.versionCode); Play rejects a version code it has already seen.
#
# Per-machine requirement is the upload key, configured in ~/.gradle/gradle.properties:
#     MARTLY_UPLOAD_STORE_FILE, MARTLY_UPLOAD_KEY_ALIAS,
#     MARTLY_UPLOAD_STORE_PASSWORD, MARTLY_UPLOAD_KEY_PASSWORD
# (keystore and passwords backed up in Dropbox/Certificates/martly/).
#
# Run from apps/mobile/:
#   ./scripts/release-android.sh

set -euo pipefail

AAB="android/app/build/outputs/bundle/release/app-release.aab"
GRADLE_PROPS="$HOME/.gradle/gradle.properties"

die() { echo "release-android: $*" >&2; exit 1; }
step() { printf '\n\033[1m▸ %s\033[0m\n' "$*"; }
prop() { grep -m1 "^$1=" "$GRADLE_PROPS" 2>/dev/null | cut -d= -f2- || true; }

case "${1:-}" in
  "") ;;
  -h|--help) sed -n '2,13p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
  *) die "unknown option: $1 (try --help)" ;;
esac

[[ -f app.json && -f package.json ]] || die "run this from apps/mobile/"

# ── Preflight ────────────────────────────────────────────────────────────
STORE_FILE=$(prop MARTLY_UPLOAD_STORE_FILE)
[[ -n "$STORE_FILE" ]] || die "MARTLY_UPLOAD_* is not set in $GRADLE_PROPS — see the header of this script"
[[ -f "$STORE_FILE" ]] || die "upload keystore not found at $STORE_FILE"
[[ -f google-services.json ]] || die "missing google-services.json"
grep -q '^GOOGLE_MAPS_APP_KEY=.' .env 2>/dev/null || die "GOOGLE_MAPS_APP_KEY is not set in .env — maps would be blank"
[[ -f .env.production ]] || die "missing .env.production (EXPO_PUBLIC_API_URL for release builds)"
PROD_API_URL=$(grep -m1 '^EXPO_PUBLIC_API_URL=' .env.production | cut -d= -f2-)
[[ "$PROD_API_URL" == https://* ]] || die "EXPO_PUBLIC_API_URL in .env.production must be an https URL"

VERSION=$(node -p "require('./app.json').expo.version")
VERSION_CODE=$(node -p "require('./app.json').expo.android.versionCode")
echo "release-android: ${VERSION} (${VERSION_CODE})"

# ── Build ────────────────────────────────────────────────────────────────
step "Regenerating android/ from app.json"
CI=1 npx expo prebuild -p android

step "Building the App Bundle"
# Gradle doesn't track .env.production, so it would reuse a JS bundle built against an old API URL
rm -rf "$AAB" android/app/build/generated/assets/createBundleReleaseJsAndAssets
(cd android && NODE_ENV=production ./gradlew bundleRelease --quiet)
[[ -f "$AAB" ]] || die "gradle finished but there is no bundle at $AAB"

# ── Verify ───────────────────────────────────────────────────────────────
step "Verifying"
# Same check as release-ios.sh: the bundle must talk to production, not the development API from .env
# Search the raw Hermes bytecode (macOS `strings` misses most of it). Hermes overlaps adjacent
# strings in its string table, so match on host and port rather than the full URL
BUNDLE="android/app/build/generated/assets/createBundleReleaseJsAndAssets/index.android.bundle"
grep -aqF "${PROD_API_URL#*://}" "$BUNDLE" || die "release bundle does not contain $PROD_API_URL"
DEV_API_URL=$(grep -m1 '^EXPO_PUBLIC_API_URL=' .env 2>/dev/null | cut -d= -f2- || true)
if [[ -n "$DEV_API_URL" ]] && grep -aqF "${DEV_API_URL#*://}" "$BUNDLE"; then
  die "release bundle contains the development API ($DEV_API_URL) — check apps/mobile/.env.production"
fi
echo "release-android: bundle talks to $PROD_API_URL"

SIGNER=$(keytool -printcert -jarfile "$AAB" | grep -m1 "Owner:" || true)
[[ "$SIGNER" != *"Android Debug"* && -n "$SIGNER" ]] || die "bundle is not signed with the upload key ($SIGNER)"
echo "release-android: signed by ${SIGNER#*Owner: }"

step "Built $AAB"
echo "Upload it in Play Console → Test and release → (track) → Create new release."
echo "Bump expo.android.versionCode in app.json before the next release."
